{"content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { callTool } from './server.mjs';

// --- Slug mode ---
test('slug - basic', async () => {
  const r = await callTool('text_transform', { text: ' Hello, MCP! ', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-mcp');
});

test('slug - multiple non-alpha runs collapse to one hyphen', async () => {
  const r = await callTool('text_transform', { text: 'foo!!!bar???baz', mode: 'slug' });
  assert.equal(r.content[0].text, 'foo-bar-baz');
});

test('slug - leading and trailing hyphens removed', async () => {
  const r = await callTool('text_transform', { text: '---hello world---', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-world');
});

test('slug - already clean text', async () => {
  const r = await callTool('text_transform', { text: 'hello-world-123', mode: 'slug' });
  assert.equal(r.content[0].text, 'hello-world-123');
});

test('slug - numbers preserved', async () => {
  const r = await callTool('text_transform', { text: 'Product 42 is great!', mode: 'slug' });
  assert.equal(r.content[0].text, 'product-42-is-great');
});

test('slug - all special chars', async () => {
  const r = await callTool('text_transform', { text: '!@#$%^&*()', mode: 'slug' });
  assert.equal(r.content[0].text, '');
});

// --- Uppercase mode ---
test('uppercase - basic', async () => {
  const r = await callTool('text_transform', { text: ' Hello World ', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HELLO WORLD');
});

test('uppercase - trim defaults true', async () => {
  const r = await callTool('text_transform', { text: '  hello  ', mode: 'uppercase' });
  assert.equal(r.content[0].text, 'HELLO');
});

test('uppercase - trim false', async () => {
  const r = await callTool('text_transform', { text: '  hello  ', mode: 'uppercase', trim: false });
  assert.equal(r.content[0].text, '  HELLO  ');
});

// --- Lowercase mode ---
test('lowercase - basic', async () => {
  const r = await callTool('text_transform', { text: ' Hello WORLD ', mode: 'lowercase' });
  assert.equal(r.content[0].text, 'hello world');
});

test('lowercase - trim defaults true', async () => {
  const r = await callTool('text_transform', { text: '  HELLO  ', mode: 'lowercase' });
  assert.equal(r.content[0].text, 'hello');
});

test('lowercase - trim false', async () => {
  const r = await callTool('text_transform', { text: '  HELLO  ', mode: 'lowercase', trim: false });
  assert.equal(r.content[0].text, '  hello  ');
});

// --- Unknown tool ---
test('unknown tool', async () => {
  await assert.rejects(
    () => callTool('unknown_tool', { text: 'x', mode: 'uppercase' }),
    { message: 'Unknown tool: unknown_tool' }
  );
});

// --- Invalid mode ---
test('invalid mode', async () => {
  await assert.rejects(
    () => callTool('text_transform', { text: 'x', mode: 'capitalize' }),
    { message: 'Invalid mode: capitalize. Must be one of: uppercase, lowercase, slug' }
  );
});

// --- Extra arguments ---
test('extra arguments rejected', async () => {
  await assert.rejects(
    () => callTool('text_transform', { text: 'x', mode: 'uppercase', extra: true }),
    { message: 'Unexpected argument: extra' }
  );
});

// --- Missing required arguments ---
test('missing text', async () => {
  await assert.rejects(
    () => callTool('text_transform', { mode: 'uppercase' }),
    { message: 'Argument "text" must be a string' }
  );
});
